rules:
- id: "vuln-nodegoat-4a4d1db7"
  pattern: |
    needle.get($URL, (error, $NEWRESPONSE) => {
      res.write($NEWRESPONSE.body);
    })
  pattern-not: |
    needle.get($URL, (error, $NEWRESPONSE, $BODY) => {
      if ($BODY) {
        res.write($BODY);
      }
    })
  languages: ["javascript"]
  message: "Potential vulnerability due to writing response body directly without checking if it exists. This can lead to unexpected behavior or errors. Ensure to check if the body is present before writing it to the response."
  severity: ERROR
  metadata:
    source-url: "github.com/OWASP/NodeGoat/commit/4a4d1db74c63fb4ff8d366551c3af006c25ead12"
    category: security
    cwe: CWE-20
    owasp: A5:2017-Broken Access Control
    references:
      - "https://owasp.org/www-project-top-ten/2017/A5_2017-Broken_Access_Control"
    technology: javascript
